#### 使用方法
调用Mindspore lite API接口使用方式:
```
// Create model
  auto model = new (std::nothrow) mindspore::Model();
  if (model == nullptr) {
    delete[] (model_buf);
    std::cerr << "New Model failed." << std::endl;
    return -1;
  }
  auto aa = model->LoadConfig("test.cfg");
  if (aa != mindspore::kSuccess) {
    delete model;
    std::cerr << "LoadConfig error" << std::endl;
    return -1;
  }
```
benchmark使用方式如下:
```
./benchmark --modelFile=your_model.ms  --device=DSP --configFile=test.cfg
```
test.cfg内容如下:
```
[kernel_tracing]
enableTracing=on
```

