### 🐞 问题详细描述

在以下代码中,生成的test_add.mindir转成test_add.ms模型,第二个输入是常量tensor,使用DSP后端跑该模型时,第二个输入只有虚拟地址,没有物理地址,使用DSP后端计算会导致结果错误.
```python

import mindspore as ms
from mindspore.train.serialization import export 
import numpy as np
from mindspore import nn, ops

class DemoModel(nn.Cell):
    def __init__(self, other):
        super(DemoModel, self).__init__()
        self.add = ops.Add()
        self.other = other

    def construct(self, x):
       x = self.add(x, self.other)
       return x

x = np.ones((100, 100)).astype(np.float32)
y = np.ones((100, 100)).astype(np.float32)
x_tensor = ms.Tensor(x)
y_tensor = ms.Tensor(y)
net = DemoModel(y_tensor)
out = net(x_tensor)
print(out)
export(net, x_tensor, file_name="test_add", file_format='MINDIR')
```
test_add.ms模型图如下:
![输入图片说明](https://foruda.gitee.com/images/1761814983966971022/1f064a3d_16320231.png "屏幕截图")

调试中发现对于常量tensor的处理在mindspore-lite/src/litert/scheduler.cc文件的FindDspKernel函数中调用CopyConstTensorData函数处理,在CopyConstTensorData处理流程是:先判断是不是常量tensor,如果是常量tensor则通过CopyTensor函数创建新的tensor,将原来的常量tensor覆盖,新的tensor分配地址时allocator是nullptr,没有通过DSP的allocator,就没有分配物理地址.
CopyConstTensorData函数代码如下:

```
int CopyConstTensorData(const std::vector<Tensor *> &tensors, int op_type) {
  // packed kernels such as conv don't need to copy because weight will be packed in kernel
  if (lite::PackWeightManager::GetInstance()->IsCopyTensor(op_type)) {
    return RET_OK;
  }

  for (auto *tensor : tensors) {
    // only copy non-copied const tensor
    if (!tensor->IsConst() && tensor->data() != nullptr) {
      MS_LOG(ERROR) << "Illegitimate tensor : " << tensor->tensor_name();
      return RET_ERROR;
    }
    if (!tensor->IsConst() || tensor->own_data()) {
      continue;
    }
    if (tensor->data_type() == kObjectTypeTensorType) {
      // tensorlist's data is nullptr since ConvertTensors
      // we never set or malloc data of tensorlist but malloc tensors in tensorlist
      MS_ASSERT(tensor->data() == nullptr);
    } else {
      auto copy_tensor = Tensor::CopyTensor(*tensor, true);
      if (copy_tensor == nullptr) {
        MS_LOG(ERROR) << "Copy tensor failed";
        return RET_ERROR;
      }
      tensor->FreeData();
      tensor->set_data(copy_tensor->data());
      tensor->set_own_data(true);
      copy_tensor->set_data(nullptr);
      delete (copy_tensor);
    }
  }
  return RET_OK;
}
```
目前想到的方案是在mindspore-lite/src/litert/kernel/dsp/dsp_kernel.cc文件的PreProcess函数中的的MallocDataDone函数进行对常量tensor的判断,如果是常量tensor就重新通过DSP的allocator分配地址,将原来tensor的虚拟地址覆盖,这样能够解决常量tensor没有物理地址问题；但是这样操作会导致性能下降,还有哪些更好的解决方案?
MallocDataDone的代码如下:

```
bool DSPKernel::MallocDataDone() {
  auto dsp_allocator = dsp_runtime_->GetAllocator();
  for (auto &in_tensor : in_tensors_) {
    if (in_tensor->IsConst() && in_tensor->allocator() == nullptr) {
      auto const_input_ptr = dsp_allocator->Malloc(in_tensor->Size());
      if (const_input_ptr == nullptr) {
        return false;
      }
      std::memcpy(const_input_ptr, in_tensor->data(), in_tensor->Size());
      free(in_tensor->data());
      in_tensor->set_data(const_input_ptr);
      in_tensor->set_own_data(true);
      in_tensor->set_allocator(dsp_allocator);
    }
  }
  for (auto &out_tensor : out_tensors_) {
    if (out_tensor->data() == nullptr) {
      return false;
    }
    auto allocator = out_tensor->allocator();
    if (allocator == nullptr) {
      return false;
    }
    auto buffer =
      reinterpret_cast<mindspore::lite::dsp::DSPAllocator *>(allocator.get())->GetDeviceMemPtr(out_tensor->data());
    if (buffer == 0) {
      return false;
    }
  }
  return true;
}
```


